faces:
@keyframes hg-breathe { 
  0%, 100% { box-shadow: rgba(111, 207, 162, 0) 0px 0px 0px 0px; }
  50% { box-shadow: rgba(111, 207, 162, 0.18) 0px 0px 0px 6px, rgba(111, 207, 162, 0.35) 0px 0px 24px; }
}

@keyframes hg-drop { 
  0% { opacity: 0; transform: translateY(-16px); }
  100% { opacity: 1; transform: none; }
}

@keyframes hg-from-left { 
  0% { opacity: 0; transform: translateX(-36px); }
  100% { opacity: 1; transform: none; }
}

@keyframes hg-from-right { 
  0% { opacity: 0; transform: translateX(36px); }
  100% { opacity: 1; transform: none; }
}

@keyframes hg-pop { 
  0% { opacity: 0; transform: scale(0.7); }
  100% { opacity: 1; transform: none; }
}

@keyframes hg-rise { 
  0% { opacity: 0; transform: translateY(16px); }
  100% { opacity: 1; transform: none; }
}

@keyframes launch-blink { 
  50% { opacity: 0.2; }
}

@keyframes lock-hunt { 
  50% { opacity: 0.72; }
}

@keyframes pdcs-blink { 
  0% { opacity: 0.35; }
  100% { opacity: 1; }
}

@keyframes pdcs-sweep { 
  100% { transform: translateX(100%); }
}

@keyframes results-rise { 
  0% { opacity: 0; transform: translateY(12px); }
  100% { opacity: 1; transform: none; }
}

@keyframes score-burst { 
  0% { opacity: 0.95; transform: scale(0.25) rotate(-9deg); }
  60% { opacity: 0.35; }
  100% { opacity: 0; transform: scale(1.25) rotate(5deg); }
}

@keyframes score-lines { 
  0% { transform: translateX(0px); }
  100% { transform: translateX(6px); }
}

@keyframes score-name-in { 
  0% { opacity: 0; transform: translateX(-14px); }
  7% { opacity: 1; transform: translateX(0px); }
  75% { opacity: 1; }
  100% { opacity: 0; transform: translateY(-10px); }
}

@keyframes score-name-slam { 
  0% { opacity: 0; transform: translateX(-42px) skewX(-16deg) scale(1.38); }
  9% { opacity: 1; transform: translateX(3px) skewX(4deg) scale(0.96); }
  15% { transform: translateX(0px) skewX(0deg) scale(1); }
  76% { opacity: 1; transform: translateX(0px); }
  100% { opacity: 0; transform: translateY(-14px); }
}

@keyframes score-pop { 
  0% { transform: scale(2.1); opacity: 0; }
  30% { opacity: 1; }
  100% { transform: scale(1); opacity: 0.7; }
}

@keyframes score-ring { 
  0% { opacity: 0.9; transform: scale(0.35); border-width: 5px; }
  100% { opacity: 0; transform: scale(3.4); border-width: 1px; }
}

@keyframes score-throb { 
  0% { transform: scale(1); }
  100% { transform: scale(1.045); }
}

@keyframes score-tier-in { 
  0% { transform: scale(0.4) rotate(-8deg); opacity: 0; }
  60% { transform: scale(1.12) rotate(2deg); opacity: 1; }
  100% { transform: scale(1) rotate(0deg); }
}

@keyframes score-verdict { 
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.82); }
  14% { opacity: 1; transform: translate(-50%, -50%) scale(1.06); }
  24% { transform: translate(-50%, -50%) scale(1); }
  70% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -74%) scale(1); }
}

@keyframes score-verdict-bail { 
  0% { opacity: 0; transform: translate(-50%, -50%) scale(1.5) skewX(-14deg); }
  8% { opacity: 1; transform: translate(-52%, -50%) scale(1) skewX(0deg); }
  13% { transform: translate(-48%, -50%); }
  18% { transform: translate(-51%, -50%); }
  23% { transform: translate(-50%, -50%); }
  70% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(0.94); }
}

@keyframes score-verdict-bank { 
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.5) rotate(-5deg); }
  12% { opacity: 1; transform: translate(-50%, -50%) scale(1.22) rotate(2deg); }
  22% { transform: translate(-50%, -50%) scale(1) rotate(0deg); }
  68% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -96%) scale(1); }
}

@keyframes signin-nudge { 
  0%, 40% { box-shadow: inset 0 0 0 2px var(--pdcs-warn), 0 0 0 4px rgba(217, 180, 108, 0.25); }
  100% { box-shadow: inset 0 0 0 1px var(--pdcs-line-soft); }
}
